import { useAuth } from "@/_core/hooks/useAuth";
import { ReleaseFooter } from "@/components/ReleaseFooter";
import { WebAppearancePanel } from "@/components/WebAppearancePanel";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { categoryEmoji, formatActivityTimestamp, normalizeLedgerWorkspace, paymentEmoji } from "@/lib/ledgerPresentation";
import { BarChart3, Bell, CalendarDays, Check, ChevronLeft, ChevronRight, Clipboard, Download, Heart, LayoutDashboard, ListChecks, LoaderCircle, LogOut, Pencil, Plus, Receipt, Search, Settings2, Sparkles, Trash2, UserRound, Users, WalletCards, WifiOff } from "lucide-react";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

type Page = "overview" | "records" | "calendar" | "analysis" | "planning" | "settings" | "profile";
type Sheet = "ledger" | "join" | "transaction" | "budget" | "total-budget" | "recurring" | "travel" | "category" | "payment" | "manage" | null;
const APP_VERSION = "1.2.9";
const workspaceSnapshotKey = (ledgerId: number) => `together-ledger-web-workspace-v1:${ledgerId}`;
const money = (value: unknown) => `NT$ ${Math.round(Number(value) || 0).toLocaleString("zh-TW")}`;
const currentMonth = () => new Date().toISOString().slice(0, 7);
const day = (value: unknown) => { const date = new Date(value as string); return Number.isNaN(date.getTime()) ? "日期待確認" : date.toLocaleDateString("zh-TW", { month: "numeric", day: "numeric", weekday: "short" }); };
const fail = (error: unknown) => toast.error(error instanceof Error ? error.message : "操作未完成，請稍後再試。");
const iconOptions = ["🍜", "🛒", "🏠", "🚗", "🎁", "💊", "🎬", "💳", "💵", "📱", "✈️", "☕"];

export default function LedgerWorkspace() {
  const [, navigate] = useLocation();
  const { user, loading, logout } = useAuth();
  const utils = trpc.useUtils();
  const [active, setActive] = useState<Page>("overview");
  const [sheet, setSheet] = useState<Sheet>(null);
  const [ledgerId, setLedgerId] = useState<number | null>(null);
  const [ledgerHome, setLedgerHome] = useState(true);
  const [standaloneProfile, setStandaloneProfile] = useState(false);
  const [ledgerSearch, setLedgerSearch] = useState("");
  const [month, setMonth] = useState(currentMonth);
  const [editing, setEditing] = useState<any>(null);
  const [confirm, setConfirm] = useState<{ title: string; text: string; run: () => void } | null>(null);
  const [cachedWorkspace, setCachedWorkspace] = useState<any>(null);
  const [lastSyncedAt, setLastSyncedAt] = useState<number | null>(null);
  const [syncError, setSyncError] = useState("");
  const [online, setOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const ledgerList = trpc.ledger.list.useQuery(undefined, { enabled: Boolean(user), refetchOnWindowFocus: false });
  const workspaceQuery = trpc.ledger.workspace.useQuery({ ledgerId: ledgerId ?? 0, month }, { enabled: Boolean(ledgerId) && !ledgerHome, refetchOnWindowFocus: false });
  const ledgers = (ledgerList.data ?? []) as any[];
  const workspace = normalizeLedgerWorkspace(workspaceQuery.data ?? cachedWorkspace) as any;
  const ledger = ledgers.find(item => item.ledger.id === ledgerId)?.ledger as any;
  const isWorkspaceRefreshing = Boolean(workspace) && workspaceQuery.isFetching && !workspaceQuery.isLoading;

  const refresh = async () => {
    setSyncError("");
    try {
      await Promise.all([
        ledgerList.refetch(),
        ledgerId ? workspaceQuery.refetch() : Promise.resolve(),
      ]);
    } catch (error) {
      setSyncError(!online ? "目前離線，正在顯示最近一次同步的帳本資料。" : "資料同步暫時失敗，可在網路恢復後重試。");
      throw error;
    }
  };
  const done = (message: string) => async () => {
    setSheet(null); setEditing(null); toast.success(message);
    void refresh().catch(() => undefined);
  };

  const enterLedger = async (item: any, message: string) => {
    await utils.ledger.list.invalidate();
    const refreshed = await ledgerList.refetch();
    const joined = (refreshed.data ?? []).find((entry: any) => entry.ledger.id === item.id)?.ledger;
    setLedgerId(joined?.id ?? item.id);
    setStandaloneProfile(false);
    setLedgerHome(false);
    setSheet(null);
    toast.success(message);
  };
  const createLedger = trpc.ledger.create.useMutation({ onSuccess: (item: any) => void enterLedger(item, "已建立空白帳本。"), onError: fail });
  const joinLedger = trpc.ledger.join.useMutation({ onSuccess: (item: any) => void enterLedger(item, "已加入共同帳本。"), onError: error => { const message = error instanceof Error ? error.message : ""; toast.error(message.includes("Unexpected token") ? "帳本服務未回傳有效資料，請重新載入最新版本後再試。" : (message || "加入帳本失敗，請確認邀請碼後再試。")); } });
  const createTransaction = trpc.ledger.createTransaction.useMutation({ onSuccess: done("收支已新增。"), onError: fail });
  const updateTransaction = trpc.ledger.updateTransaction.useMutation({ onSuccess: done("收支已更新。"), onError: fail });
  const deleteTransaction = trpc.ledger.deleteTransaction.useMutation({ onSuccess: done("收支已刪除。"), onError: fail });
  const settle = trpc.ledger.settlement.markSettled.useMutation({ onSuccess: done("本月結算已完成。"), onError: fail });
  const saveBudget = trpc.ledger.upsertBudget.useMutation({ onSuccess: done("分類預算已儲存。"), onError: fail });
  const removeBudget = trpc.ledger.deleteBudget.useMutation({ onSuccess: done("分類預算已刪除。"), onError: fail });
  const createRecurring = trpc.ledger.createRecurring.useMutation({ onSuccess: done("固定收支已建立。"), onError: fail });
  const updateRecurring = trpc.ledger.updateRecurring.useMutation({ onSuccess: done("固定收支已更新。"), onError: fail });
  const removeRecurring = trpc.ledger.deleteRecurring.useMutation({ onSuccess: done("固定收支已刪除。"), onError: fail });
  const syncRecurring = trpc.ledger.syncRecurring.useMutation({ onSuccess: done("已同步到期固定收支。"), onError: fail });
  const createTravel = trpc.ledger.createTravelPlan.useMutation({ onSuccess: done("出遊規劃已建立。"), onError: fail });
  const removeTravel = trpc.ledger.deleteTravelPlan.useMutation({ onSuccess: done("出遊規劃已刪除。"), onError: fail });
  const createCategory = trpc.ledger.createCategory.useMutation({ onSuccess: done("分類已新增。"), onError: fail });
  const updateCategory = trpc.ledger.updateCategory.useMutation({ onSuccess: done("分類已更新。"), onError: fail });
  const archiveCategory = trpc.ledger.archiveCategory.useMutation({ onSuccess: done("分類已隱藏。"), onError: fail });
  const restoreCategory = trpc.ledger.setCategoryActive.useMutation({ onSuccess: done("分類已恢復。"), onError: fail });
  const removeCategory = trpc.ledger.deleteCategory.useMutation({ onSuccess: done("分類已永久刪除。"), onError: fail });
  const createPayment = trpc.ledger.createPaymentMethod.useMutation({ onSuccess: done("支付方式已新增。"), onError: fail });
  const updatePayment = trpc.ledger.updatePaymentMethod.useMutation({ onSuccess: done("支付方式已更新。"), onError: fail });
  const archivePayment = trpc.ledger.archivePaymentMethod.useMutation({ onSuccess: done("支付方式已隱藏。"), onError: fail });
  const restorePayment = trpc.ledger.setPaymentMethodActive.useMutation({ onSuccess: done("支付方式已恢復。"), onError: fail });
  const removePayment = trpc.ledger.deletePaymentMethod.useMutation({ onSuccess: done("支付方式已永久刪除。"), onError: fail });
  const rename = trpc.ledger.rename.useMutation({ onSuccess: done("帳本名稱已更新。"), onError: fail });
  const transfer = trpc.ledger.transferOwnership.useMutation({ onSuccess: done("帳本持有權已轉讓。"), onError: fail });
  const leave = trpc.ledger.leave.useMutation({ onSuccess: done("帳本設定已更新。"), onError: fail });
  const updateRole = trpc.ledger.updateMemberRole.useMutation({ onSuccess: done("成員權限已更新。"), onError: fail });

  useEffect(() => {
    if (ledgerList.isLoading) return;
    const first = ledgers[0]?.ledger.id;
    if (first && !ledgers.some(item => item.ledger.id === ledgerId)) setLedgerId(first);
    if (!first) setLedgerId(null);
  }, [ledgerId, ledgerList.isLoading, ledgers]);

  useEffect(() => {
    const markOnline = () => setOnline(true);
    const markOffline = () => setOnline(false);
    window.addEventListener("online", markOnline);
    window.addEventListener("offline", markOffline);
    return () => { window.removeEventListener("online", markOnline); window.removeEventListener("offline", markOffline); };
  }, []);

  useEffect(() => {
    if (!ledgerId) { setCachedWorkspace(null); setLastSyncedAt(null); return; }
    const key = workspaceSnapshotKey(ledgerId);
    if (workspaceQuery.data) {
      const savedAt = Date.now();
      setCachedWorkspace(workspaceQuery.data);
      setLastSyncedAt(savedAt);
      try { localStorage.setItem(key, JSON.stringify({ savedAt, workspace: workspaceQuery.data })); } catch {}
      return;
    }
    try {
      const saved = localStorage.getItem(key);
      if (saved) {
        const snapshot = JSON.parse(saved);
        if (snapshot?.workspace) { setCachedWorkspace(snapshot.workspace); setLastSyncedAt(Number(snapshot.savedAt) || null); }
      }
    } catch {}
  }, [ledgerId, workspaceQuery.data, workspaceQuery.dataUpdatedAt]);

  if (loading) return <AuthLoadingSkeleton />;
  if (!user) return <AccessGate onLogin={() => navigate("/login")} />;

  const memberName = (userId: number) => workspace?.members?.find((item: any) => item.member.userId === userId)?.user?.name || "帳本成員";
  const category = (categoryId: number) => workspace?.categories?.find((item: any) => item.id === categoryId);
  const payment = (paymentId: number) => workspace?.paymentMethods?.find((item: any) => item.id === paymentId);
  const openTransaction = (transaction?: any) => { setEditing(transaction ?? null); setSheet("transaction"); };
  const navigation: Array<[Page, string, any]> = [["overview", "總覽", LayoutDashboard], ["records", "收支紀錄", Receipt], ["calendar", "月曆", CalendarDays], ["analysis", "分析", BarChart3], ["planning", "規劃", ListChecks], ["settings", "帳本設定", Settings2], ["profile", "個人設定", Sparkles]];
  const mobileNavigation = navigation.filter(([key]) => ["overview", "calendar", "analysis", "planning", "settings"].includes(key));
  const selectPage = (page: Page) => {
    setActive(page);
    if (typeof window !== "undefined") {
      const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
      window.requestAnimationFrame(() => window.scrollTo({ top: 0, behavior: reduceMotion ? "auto" : "smooth" }));
    }
  };

  const selectLedger = (nextLedgerId: number) => {
    setLedgerId(nextLedgerId);
    setActive("overview");
    setLedgerHome(false);
    setLedgerSearch("");
  };

  if (ledgerHome && standaloneProfile) {
    return <div className="web-ledger-shell min-h-screen bg-[var(--background)] px-4 py-5 text-[var(--foreground)] sm:px-7"><div className="mx-auto w-full max-w-5xl"><button type="button" onClick={() => setStandaloneProfile(false)} className="mb-5 inline-flex min-h-11 items-center gap-1 rounded-xl px-2 text-sm font-semibold text-[#9A6870]"><ChevronLeft size={17} />返回我的帳本</button><Profile workspace={null} onRefresh={() => void refresh().catch(() => undefined)} /><div className="mt-5"><WebAppearancePanel /></div></div></div>;
  }

  if (ledgerHome) {
    return <>
      <LedgerHomePage
        user={user}
        ledgers={ledgers}
        query={ledgerSearch}
        onQueryChange={setLedgerSearch}
        lastSyncedAt={lastSyncedAt}
        refreshing={ledgerList.isFetching}
        online={online}
        onRefresh={() => void refresh().catch(() => undefined)}
        onSelect={selectLedger}
        onCreate={() => setSheet("ledger")}
        onJoin={() => setSheet("join")}
        onProfile={() => setStandaloneProfile(true)}
      />
      <CreateLedgerDialog open={sheet === "ledger"} onClose={() => setSheet(null)} onSubmit={(input) => createLedger.mutate(input as any)} />
      <TextDialog open={sheet === "join"} title="使用邀請碼加入帳本" description="加入後兩端會看到完全相同的帳本資料。" label="邀請碼" submit="加入帳本" onClose={() => setSheet(null)} onSubmit={(value: string) => joinLedger.mutate({ inviteCode: value.toUpperCase() } as any)} />
    </>;
  }

  return (
    <div className="web-ledger-shell min-h-screen bg-[var(--background)] text-[var(--foreground)]">
      <div className="mx-auto flex min-h-screen w-full max-w-[1440px]">
        <aside className="ledger-sidebar hidden w-72 shrink-0 px-5 py-6 lg:flex lg:flex-col">
          <button type="button" onClick={() => navigate("/")} className="flex items-center gap-3 px-2 text-left"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#F6E2E4] text-[#AF6171]"><Heart size={21} fill="currentColor" /></span><span><b className="block font-serif text-xl">共帳</b><small className="block text-[10px] tracking-[0.2em] text-[#A48C84]">TOGETHER LEDGER</small></span></button>
          <p className="mt-9 px-3 text-[10px] font-bold tracking-[0.18em] text-[#B39D95]">我的帳本</p>
          <div className="mt-3 space-y-1">{ledgers.map(item => <button key={item.ledger.id} type="button" onClick={() => setLedgerId(item.ledger.id)} className={`flex w-full items-center gap-3 rounded-2xl px-3 py-3 text-left ${item.ledger.id === ledgerId ? "bg-[#F7E8E8] text-[#9D5C69]" : "text-[#7E6961] hover:bg-[#FAF3F0]"}`}><span className="flex h-8 w-8 items-center justify-center rounded-xl bg-white"><WalletCards size={16} /></span><span className="min-w-0 flex-1"><b className="block truncate text-sm">{item.ledger.name}</b><small className="block text-[11px] text-[#A68F86]">{item.ledger.type === "couple" ? "共同帳本" : item.ledger.type}</small></span></button>)}<button type="button" onClick={() => setSheet("ledger")} className="flex w-full items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold text-[#A56570] hover:bg-[#FAF3F0]"><Plus size={16} />新增帳本</button></div>
          {ledger && <nav className="mt-7 space-y-1">{navigation.map(([key, label, Icon]) => <button key={key} type="button" onClick={() => selectPage(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold ${active === key ? "bg-[#F5E6E6] text-[#A35F6D]" : "text-[#827068] hover:bg-[#FAF3F0]"}`}><Icon size={17} />{label}</button>)}</nav>}
          <div className="mt-auto rounded-2xl border border-[#EFDCD6] bg-[#FEF7F4] p-4"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#F4DDE0] text-[#A95F70]"><Users size={16} /></span><span className="min-w-0"><b className="block truncate text-sm">{user.name || "共帳使用者"}</b><small className="block truncate text-[11px] text-[#A18B83]">{user.email}</small></span></div><Button type="button" variant="ghost" onClick={() => void logout()} className="mt-3 h-8 w-full justify-start px-1 text-xs"><LogOut size={14} className="mr-2" />登出</Button></div>
        </aside>
        <main data-page={active} className="ledger-main min-w-0 flex-1 px-4 py-5 sm:px-7 sm:py-7">
          <header className="ledger-workspace-header flex flex-col gap-4 border-b border-[#E9DED8] pb-5 sm:flex-row sm:items-center sm:justify-between"><div><button type="button" onClick={() => { setStandaloneProfile(false); setLedgerHome(true); }} className="mb-2 inline-flex min-h-11 items-center gap-1 rounded-xl px-2 text-sm font-semibold text-[#9A6870] hover:text-[#7D4C55]"><ChevronLeft size={17} />返回我的帳本</button><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-bold sm:text-3xl">{ledger?.name || "我的共同帳本"}</h1>{isWorkspaceRefreshing && <span className="inline-flex items-center gap-1 rounded-full bg-[#F9EEE9] px-2 py-1 text-[11px] font-semibold text-[#9A6870]" role="status"><LoaderCircle size={12} className="animate-spin" />同步中</span>}</div>{ledger && <p className="mt-1 text-xs text-[#9A857D]">{lastSyncedAt ? `上次同步：${new Date(lastSyncedAt).toLocaleTimeString("zh-TW", { hour: "2-digit", minute: "2-digit" })}` : "尚未完成同步"}</p>}</div><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" onClick={() => void refresh().catch(() => undefined)} disabled={isWorkspaceRefreshing} className="rounded-xl border-[#DDC7C0] bg-white text-[#875A61]"><LoaderCircle size={16} className={`mr-2 ${isWorkspaceRefreshing ? "animate-spin" : ""}`} />重新整理</Button><Button type="button" variant="outline" onClick={() => setSheet("join")} className="rounded-xl border-[#DDC7C0] bg-white text-[#875A61]"><Users size={16} className="mr-2" />加入帳本</Button>{ledger && <Button type="button" onClick={() => openTransaction()} className="rounded-xl bg-[#B56C78] text-white hover:bg-[#A35B68]"><Plus size={16} className="mr-2" />新增收支</Button>}</div></header>
          {(syncError || !online) && <div className="mt-4 flex flex-wrap items-center gap-3 rounded-2xl border border-[#ECD6CC] bg-[#FFF7F2] px-4 py-3 text-sm text-[#815D53]" role="alert"><WifiOff size={18} className="shrink-0 text-[#B56C78]" /><span className="min-w-0 flex-1">{syncError || "目前離線，顯示最近一次同步的資料。"}</span><Button type="button" size="sm" variant="outline" onClick={() => void refresh().catch(() => undefined)} className="rounded-lg border-[#DDBDB2] bg-white">重試同步</Button></div>}
          {!ledgerList.isLoading && !ledger ? <EmptyLedger onCreate={() => setSheet("ledger")} onJoin={() => setSheet("join")} /> : workspaceQuery.isLoading && !workspace ? <Loading /> : workspace ? <section key={`${ledgerId}-${active}`} className="ledger-content-enter py-6">
            {active === "overview" && <AppAlignedOverview workspace={workspace} ledger={ledger} currentUserId={user.id} memberName={memberName} getCategory={category} onAdd={() => openTransaction()} onEdit={openTransaction} onDelete={(item: any) => setConfirm({ title: "刪除這筆收支？", text: "刪除後會同步移除所有成員看到的資料。", run: () => deleteTransaction.mutate({ ledgerId: ledgerId!, transactionId: item.id } as any) })} onShowRecords={() => selectPage("records")} onSettle={() => setConfirm({ title: "確認本月結算？", text: "此操作會建立結算紀錄，請確認款項已交付。", run: () => settle.mutate({ ledgerId: ledgerId!, month } as any) })} />}
            {active === "records" && <Records workspace={workspace} getCategory={category} getPayment={payment} memberName={memberName} onEdit={openTransaction} onDelete={(item: any) => setConfirm({ title: "刪除這筆收支？", text: "刪除後不可復原。", run: () => deleteTransaction.mutate({ ledgerId: ledgerId!, transactionId: item.id } as any) })} />}
            {active === "calendar" && <AppCalendar workspace={workspace} month={month} setMonth={setMonth} getCategory={category} memberName={memberName} onEdit={openTransaction} />}
            {active === "analysis" && <Analysis workspace={workspace} month={month} setMonth={setMonth} />}
            {active === "planning" && <Planning workspace={workspace} getCategory={category} getPayment={payment} onBudget={() => setSheet("budget")} onTotalBudget={() => setSheet("total-budget")} onRecurring={() => { setEditing(null); setSheet("recurring"); }} onEditRecurring={(item: any) => { setEditing(item); setSheet("recurring"); }} onTravel={() => setSheet("travel")} onSync={() => syncRecurring.mutate({ ledgerId: ledgerId! } as any)} onDeleteBudget={(id: number) => setConfirm({ title: "刪除此預算？", text: "分類預算將不再顯示於本月規劃。", run: () => removeBudget.mutate({ ledgerId: ledgerId!, budgetId: id } as any) })} onDeleteRecurring={(id: number) => setConfirm({ title: "刪除固定收支？", text: "不會刪除已經產生的歷史交易。", run: () => removeRecurring.mutate({ ledgerId: ledgerId!, recurringId: id } as any) })} onDeleteTravel={(id: number) => setConfirm({ title: "刪除出遊規劃？", text: "此規劃資料將被永久移除。", run: () => removeTravel.mutate({ ledgerId: ledgerId!, planId: id } as any) })} />}
            {active === "settings" && <LedgerSettings workspace={workspace} ledger={ledger} userId={user.id} memberName={memberName} onManage={() => setSheet("manage")} onEditCategory={(item?: any) => { setEditing(item ?? null); setSheet("category"); }} onEditPayment={(item?: any) => { setEditing(item ?? null); setSheet("payment"); }} onArchiveCategory={(id: number) => archiveCategory.mutate({ ledgerId: ledgerId!, categoryId: id } as any)} onRestoreCategory={(id: number) => restoreCategory.mutate({ ledgerId: ledgerId!, categoryId: id, isActive: 1 } as any)} onDeleteCategory={(id: number) => setConfirm({ title: "永久刪除分類？", text: "已被使用的分類只能隱藏。", run: () => removeCategory.mutate({ ledgerId: ledgerId!, categoryId: id } as any) })} onArchivePayment={(id: number) => archivePayment.mutate({ ledgerId: ledgerId!, paymentMethodId: id } as any)} onRestorePayment={(id: number) => restorePayment.mutate({ ledgerId: ledgerId!, paymentMethodId: id, isActive: 1 } as any)} onDeletePayment={(id: number) => setConfirm({ title: "永久刪除支付方式？", text: "已被使用的方式只能隱藏。", run: () => removePayment.mutate({ ledgerId: ledgerId!, paymentMethodId: id } as any) })} onRole={(userId: number, role: "admin" | "member" | "viewer") => updateRole.mutate({ ledgerId: ledgerId!, userId, role } as any)} onLeave={(action: "leave" | "delete") => setConfirm({ title: action === "delete" ? "刪除整個帳本？" : "確認退出帳本？", text: action === "delete" ? "帳本與所有資料將永久刪除。" : "退出後仍可使用邀請碼再次加入。", run: () => leave.mutate({ ledgerId: ledgerId!, action } as any) })} />}
            {active === "profile" && <><Profile workspace={workspace} onRefresh={refresh} /><WebAppearancePanel /></>}
          </section> : <EmptyText text="帳本資料暫時無法載入，請稍後再試。" />}
          <nav aria-label="帳本行動版主要功能導覽" className="ledger-mobile-nav mt-6 grid grid-cols-5 gap-1 rounded-2xl p-1.5 lg:hidden">{mobileNavigation.map(([key, label, Icon]) => <button key={key} type="button" onClick={() => selectPage(key)} className={`flex min-w-0 flex-col items-center gap-1 rounded-xl px-1 py-2.5 text-[10px] leading-tight ${active === key ? "bg-[#F7E8E8] text-[#9D5C69]" : "text-[#8E7770] hover:bg-[#FBF6F3]"}`}><Icon size={18} />{label}</button>)}</nav>
          <ReleaseFooter compact />
        </main>
      </div>
      <CreateLedgerDialog open={sheet === "ledger"} onClose={() => setSheet(null)} onSubmit={(input) => createLedger.mutate(input as any)} />
      <TextDialog open={sheet === "join"} title="使用邀請碼加入帳本" description="加入後兩端會看到完全相同的帳本資料。" label="邀請碼" submit="加入帳本" onClose={() => setSheet(null)} onSubmit={(value: string) => joinLedger.mutate({ inviteCode: value.toUpperCase() } as any)} />
      <TransactionDialog open={sheet === "transaction"} workspace={workspace} ledgerId={ledgerId!} editing={editing} onClose={() => { setSheet(null); setEditing(null); }} onCreate={(input: any) => createTransaction.mutate(input)} onUpdate={(input: any) => updateTransaction.mutate(input)} />
      <BudgetDialog open={sheet === "budget" || sheet === "total-budget"} totalBudget={sheet === "total-budget"} workspace={workspace} ledgerId={ledgerId!} month={month} onClose={() => setSheet(null)} onSave={(input: any) => saveBudget.mutate(input)} />
      <RecurringDialog open={sheet === "recurring"} workspace={workspace} ledgerId={ledgerId!} editing={sheet === "recurring" ? editing : null} onClose={() => { setSheet(null); setEditing(null); }} onSave={(input: any) => editing ? updateRecurring.mutate(input) : createRecurring.mutate(input)} />
      <TravelDialog open={sheet === "travel"} ledgerId={ledgerId!} onClose={() => setSheet(null)} onSave={(input: any) => createTravel.mutate(input)} />
      <EntityDialog open={sheet === "category" || sheet === "payment"} type={sheet === "payment" ? "payment" : "category"} ledgerId={ledgerId!} entity={editing} onClose={() => { setSheet(null); setEditing(null); }} onCategory={(input: any) => editing ? updateCategory.mutate(input) : createCategory.mutate(input)} onPayment={(input: any) => editing ? updatePayment.mutate(input) : createPayment.mutate(input)} />
      <ManageDialog open={sheet === "manage"} ledger={ledger} workspace={workspace} userId={user.id} onClose={() => setSheet(null)} onRename={(name: string) => rename.mutate({ ledgerId: ledgerId!, name } as any)} onTransfer={(targetUserId: number) => transfer.mutate({ ledgerId: ledgerId!, targetUserId } as any)} />
      <ConfirmDialog request={confirm} onClose={() => setConfirm(null)} />
    </div>
  );
}

function LedgerHomePage({ user, ledgers, query, onQueryChange, lastSyncedAt, refreshing, online, onRefresh, onSelect, onCreate, onJoin, onProfile }: { user: any; ledgers: any[]; query: string; onQueryChange: (value: string) => void; lastSyncedAt: number | null; refreshing: boolean; online: boolean; onRefresh: () => void; onSelect: (ledgerId: number) => void; onCreate: () => void; onJoin: () => void; onProfile: () => void }) {
  const filteredLedgers = useMemo(() => {
    const keyword = query.trim().toLocaleLowerCase();
    return keyword ? ledgers.filter(item => String(item.ledger?.name || "").toLocaleLowerCase().includes(keyword)) : ledgers;
  }, [ledgers, query]);
  const syncedLabel = lastSyncedAt ? new Date(lastSyncedAt).toLocaleTimeString("zh-TW", { hour: "2-digit", minute: "2-digit" }) : "剛剛";
  return <div className="ledger-home-shell min-h-screen text-[var(--foreground)]">
    <div className="ledger-home-safe mx-auto w-full max-w-3xl px-5 pb-12 pt-7 sm:px-8 sm:pt-10">
      <header className="ledger-home-header flex items-center justify-between gap-4">
        <div className="flex min-w-0 items-center gap-3.5"><span className="ledger-home-mark flex h-[68px] w-[68px] shrink-0 items-center justify-center rounded-[22px]"><Heart size={33} strokeWidth={2} /></span><div className="min-w-0"><h1 className="text-safe-wrap text-[31px] font-bold leading-tight tracking-[-0.035em]">我的帳本</h1><p className="mt-1 text-sm text-[#7B8F9C]">選擇要進入的共同空間</p></div></div>
        <button type="button" onClick={onProfile} aria-label="個人設定" className="ledger-home-profile flex h-[58px] w-[58px] shrink-0 items-center justify-center rounded-[21px] text-[#56869C] transition-transform active:scale-95"><UserRound size={24} /></button>
      </header>

      <main className="mt-7">
        <p className="text-xs font-bold tracking-[0.17em] text-[#5F93AB]">MY LEDGERS</p>
        <h2 className="mt-5 text-safe-wrap text-[36px] font-bold leading-[1.1] tracking-[-0.04em]">選擇共同帳本</h2>
        <p className="mt-4 max-w-[34rem] text-safe-wrap text-[17px] leading-8 text-[#788D99]">先選擇要進入的空間，也可以建立新的帳本或使用邀請碼加入。</p>
        <button type="button" onClick={onRefresh} className="ledger-home-sync mt-10 flex w-full items-start gap-3 rounded-2xl px-3 py-3 text-left" aria-label="重新同步帳本資料">
          <span className="mt-0.5 shrink-0 text-[#6E9E9F]">{refreshing ? <LoaderCircle className="animate-spin" size={24} /> : online ? <Check size={24} /> : <WifiOff size={24} />}</span><span className="min-w-0"><b className="block text-base text-[#3F5B68]">{online ? "資料同步完成" : "正在顯示離線資料"}</b><span className="mt-1 block text-safe-wrap text-sm text-[#7D919C]">{online ? `最後同步：${syncedLabel}，下拉即可重新整理。` : "網路恢復後可點擊重新整理。"}</span></span>
        </button>
        <label className="ledger-home-search mt-8 flex items-center gap-3 rounded-[23px] px-5 py-4"><Search size={22} className="shrink-0 text-[#8096A2]" /><Input value={query} onChange={event => onQueryChange(event.target.value)} className="h-auto min-w-0 border-0 bg-transparent p-0 text-[17px] shadow-none placeholder:text-[#93A4AD] focus-visible:ring-0" placeholder="搜尋帳本名稱" aria-label="搜尋帳本名稱" /></label>
        <div className="mt-7 flex items-center justify-between gap-3"><p className="text-sm text-[#718895]">{filteredLedgers.length} 個帳本</p>{query.trim() && <button type="button" onClick={() => onQueryChange("")} className="text-sm font-semibold text-[#5E8FA8]">清除搜尋</button>}</div>
        <section className="mt-4 space-y-3" aria-label="共同帳本清單">
          {filteredLedgers.length ? filteredLedgers.map(item => <button key={item.ledger.id} type="button" onClick={() => onSelect(item.ledger.id)} className="ledger-home-card flex w-full min-w-0 items-center gap-4 rounded-[27px] px-5 py-5 text-left transition-transform active:scale-[0.985]"><span className="ledger-home-card-icon flex h-[62px] w-[62px] shrink-0 items-center justify-center rounded-[21px] text-[#5E91AA]">{item.ledger.icon || (item.ledger.type === "couple" ? <Heart size={29} /> : <Users size={28} />)}</span><span className="min-w-0 flex-1"><b className="block truncate text-xl text-[#344E5C]">{item.ledger.name}</b><span className="mt-1 block text-sm text-[#7D929D]">點擊進入共同帳本</span></span><ChevronRight size={30} className="shrink-0 text-[#6F909D]" /></button>) : <div className="ledger-home-empty rounded-[27px] px-5 py-8 text-center text-sm leading-7 text-[#748B97]">找不到符合的帳本名稱。</div>}
        </section>
        <div className="mt-5 grid grid-cols-2 gap-3"><Button type="button" onClick={onCreate} className="ledger-home-primary h-[62px] min-w-0 rounded-[24px] text-lg font-bold"><Plus size={24} className="mr-2" />建立帳本</Button><Button type="button" onClick={onJoin} variant="outline" className="ledger-home-secondary h-[62px] min-w-0 rounded-[24px] border-0 text-lg font-bold"><Users size={22} className="mr-2" />加入帳本</Button></div>
      </main>
    </div>
  </div>;
}

function AccessGate({ onLogin }: { onLogin: () => void }) { return <div className="flex min-h-screen items-center justify-center bg-[#F7F4F1] p-5"><div className="w-full max-w-md rounded-[28px] border border-[#EBDDD7] bg-[#FFFDFC] p-8 text-center"><span className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-[#F6E3E4] text-[#B06070]"><Heart size={29} fill="currentColor" /></span><h1 className="mt-5 text-2xl font-bold">先登入，再開啟共同帳本</h1><p className="mt-3 text-sm leading-7 text-[#8D7770]">請使用 Android App 相同的電子信箱與密碼。兩端使用同一個帳號、帳本及收支資料。</p><Button type="button" onClick={onLogin} className="mt-6 w-full rounded-xl bg-[#B56C78]">前往登入／註冊</Button></div></div> }
function EmptyLedger({ onCreate, onJoin }: { onCreate: () => void; onJoin: () => void }) { return <section className="mx-auto flex max-w-2xl flex-col items-center px-4 py-20 text-center"><span className="flex h-20 w-20 items-center justify-center rounded-3xl bg-[#F6E4E4] text-[#B06070]"><Heart size={34} fill="currentColor" /></span><h2 className="mt-6 text-2xl font-bold">從一個空白帳本開始</h2><p className="mt-3 max-w-lg text-sm leading-7 text-[#8D7770]">建立帳本或使用邀請碼加入。網頁與 Android App 的帳本資料會即時共用。</p><div className="mt-7 flex gap-3"><Button type="button" onClick={onCreate} className="rounded-xl bg-[#B56C78]"><Plus size={16} className="mr-2" />建立帳本</Button><Button type="button" onClick={onJoin} variant="outline" className="rounded-xl">使用邀請碼加入</Button></div></section> }
function AuthLoadingSkeleton() { return <div className="flex min-h-screen items-center justify-center bg-[var(--background)] p-5"><div className="w-full max-w-5xl overflow-hidden rounded-[32px] border border-[var(--border)] bg-[var(--card)] shadow-[0_24px_70px_rgba(86,58,50,0.1)]"><div className="grid lg:grid-cols-[1.03fr_0.97fr]"><div className="min-h-72 bg-[#5B4142] p-8 sm:p-10"><Skeleton className="h-11 w-40 bg-white/15" /><Skeleton className="mt-14 h-11 w-4/5 bg-white/15" /><Skeleton className="mt-3 h-11 w-3/5 bg-white/15" /><Skeleton className="mt-8 h-4 w-full bg-white/10" /><Skeleton className="mt-3 h-4 w-4/5 bg-white/10" /></div><div className="p-8 sm:p-10"><Skeleton className="h-10 w-full" /><Skeleton className="mt-9 h-7 w-40" /><Skeleton className="mt-3 h-4 w-4/5" /><Skeleton className="mt-8 h-11 w-full" /><Skeleton className="mt-4 h-11 w-full" /><Skeleton className="mt-6 h-11 w-full bg-[#EBCFD2]" /><p className="mt-5 text-center text-xs text-[var(--muted-foreground)]" role="status">正在安全確認登入狀態…</p></div></div></div></div> }
function Loading() { return <section className="grid gap-4 py-7 md:grid-cols-3" aria-label="正在載入帳本資料" role="status"><Skeleton className="h-36 rounded-3xl bg-[#EFE4DF] md:col-span-2" /><Skeleton className="h-36 rounded-3xl bg-[#EFE4DF]" /><Skeleton className="h-72 rounded-3xl bg-[#F2EAE6] md:col-span-3" /><span className="sr-only">正在同步共同帳本資料</span></section> }
function EmptyText({ text }: { text: string }) { return <p className="py-8 text-center text-sm text-[#9A847B]">{text}</p> }
function Card({ title, text, children }: { title: string; text?: string; children: React.ReactNode }) { if (title === "分類支出") return null; return <section className="ledger-card rounded-3xl p-4 shadow-[0_10px_28px_rgba(88,59,51,0.04)] sm:p-6"><h2 className="text-lg font-bold">{title}</h2>{text && <p className="mt-1 text-sm text-[#937D74]">{text}</p>}<div className="mt-5">{children}</div></section> }
function Metric({ label, value, tone }: { label: string; value: string; tone: string }) { return <article className="ledger-card ledger-metric rounded-3xl p-4 sm:p-5"><p className="text-sm text-[#947E75]">{label}</p><b className={`mt-2 block text-2xl ${tone}`}>{value}</b></article> }
function AppAlignedOverview({ workspace, ledger, currentUserId, memberName, getCategory, onAdd, onEdit, onDelete, onShowRecords, onSettle }: any) { const [copied, setCopied] = useState(false); const transactions = workspace.calendarTransactions ?? []; const members = workspace.members ?? []; const names = members.map((item: any) => item.user?.name || item.user?.email || "成員").join(" ＆ "); const payments = members.map((member: any) => ({ ...member, total: transactions.filter((item: any) => item.payerId === member.member.userId && item.type === "expense").reduce((sum: number, item: any) => sum + Number(item.amount || 0), 0) })); const topCategory = workspace.analytics?.categories?.[0]; const copy = async () => { try { await navigator.clipboard.writeText(ledger.inviteCode); setCopied(true); setTimeout(() => setCopied(false), 1200); toast.success("邀請碼已複製。"); } catch { toast.error("目前無法複製邀請碼。") } }; return <div className="ledger-home-overview space-y-4 sm:space-y-5"><section className="ledger-home-hero rounded-[28px] p-6 sm:p-8"><p className="text-xs font-semibold tracking-[0.16em] text-[#E8CBCD]">{ledger.type === "couple" ? "情侶共同帳本" : "多人共同帳本"}</p><h2 className="mt-3 text-safe-wrap font-serif text-3xl font-semibold">{ledger.name}</h2><p className="mt-2 text-sm leading-6 text-[#F1DDDA]">把每一份共同支出清楚記下來，讓生活更透明。</p><div className="mt-5 flex min-w-0 items-center gap-2 text-sm text-[#F8E9E5]"><Users size={17} className="shrink-0" /><span className="truncate">{members.length} 位成員 · {names || "等待成員加入"}</span></div></section><div className="ledger-home-action-row"><Button type="button" onClick={onAdd} className="rounded-2xl bg-[#B56C78] px-4 text-white hover:bg-[#A35B68]"><Plus size={18} className="mr-2" />新增收支</Button><button type="button" onClick={() => void copy()} className="ledger-home-invite rounded-2xl px-3 py-2 text-left transition-colors hover:bg-[#FBF4F1]" aria-label="複製帳本邀請碼"><span className="block text-[10px] font-semibold tracking-[0.12em] text-[#A28A81]">邀請碼</span><b className="mt-0.5 block font-mono text-sm tracking-[0.14em]">{copied ? "已複製" : ledger.inviteCode}</b></button></div><div className="ledger-home-stats"><Metric label="本月收入" value={money(workspace.analytics?.income)} tone="text-[#5E856A]" /><Metric label="本月支出" value={money(workspace.analytics?.expense)} tone="text-[#AD5D68]" /></div><section className="ledger-home-balance rounded-3xl p-5"><div className="min-w-0"><p className="text-sm text-[#947E75]">本月結餘</p><b className="mt-1 block truncate text-2xl text-[#735D7A]">{money(workspace.analytics?.balance)}</b></div><BarChart3 size={36} className="shrink-0 text-[#B56C78]" /></section><Card title="雙方支付總覽" text="本月"><div className="max-h-48 overflow-y-auto pr-1">{payments.length ? payments.map((member: any) => <div key={member.member.userId} className="ledger-member-row flex min-w-0 items-center gap-3 py-3"><span className="ledger-avatar flex h-10 w-10 shrink-0 items-center justify-center rounded-xl font-semibold">{(member.user?.name || member.user?.email || "成").slice(0, 1)}</span><span className="min-w-0 flex-1"><b className="block truncate text-sm">{member.member.userId === currentUserId ? "你" : member.user?.name || member.user?.email || "成員"}</b><small className="block truncate text-xs text-[#9A847B]">{member.member.role === "admin" ? "管理員" : member.member.role === "viewer" ? "檢視者" : "成員"}</small></span><b className="shrink-0 text-sm text-[#875E66]">{money(member.total)}</b></div>) : <EmptyText text="等待成員加入後即可查看支付總覽。" />}</div></Card><Card title="最近收支"><div className="flex items-center justify-between gap-3"><p className="text-sm text-[#937D74]">近期共同帳本資料</p><Button type="button" size="sm" variant="ghost" onClick={onShowRecords} className="shrink-0 rounded-lg px-2 text-[#A35F6D]">完整檢視</Button></div>{transactions.length ? <div className="mt-3 divide-y divide-[#F1E7E2]">{transactions.slice(0, 8).map((item: any) => <TransactionRow key={item.id} item={item} category={getCategory(item.categoryId)} payer={memberName(item.payerId)} onEdit={() => onEdit(item)} onDelete={() => onDelete(item)} />)}</div> : <EmptyText text="目前沒有收支記錄。" />}</Card><Card title="分類支出">{workspace.analytics?.categories?.length ? <div className="space-y-4">{workspace.analytics.categories.slice(0, 6).map((item: any) => <div key={item.id}><div className="flex min-w-0 justify-between gap-3 text-sm"><span className="min-w-0 truncate">{categoryEmoji(item)} {item.name}</span><b className="shrink-0">{money(item.amount)}</b></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[#F1E7E2]"><div className="h-full rounded-full" style={{ width: `${Math.min(100, Number(item.amount) / Math.max(Number(workspace.analytics.expense), 1) * 100)}%`, backgroundColor: item.color }} /></div></div>)}</div> : <EmptyText text="尚無可分析的支出。" />}</Card><section className="ledger-card flex items-start gap-3 rounded-3xl p-5"><Sparkles size={21} className="mt-0.5 shrink-0 text-[#B56C78]" /><div className="min-w-0"><h2 className="font-bold">共同財務摘要</h2><p className="mt-1 text-safe-wrap text-sm leading-6 text-[#937D74]">{topCategory ? `本月最高支出分類是「${topCategory.name}」，共 ${money(topCategory.amount)}。` : "目前還沒有收支記錄，新增第一筆交易後會在這裡看到分析。"}</p></div></section><section className="ledger-card flex items-center gap-3 rounded-3xl p-5"><span className="ledger-activity-icon flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl"><WalletCards size={21} /></span><div className="min-w-0 flex-1"><h2 className="font-bold">目前結算狀態</h2><p className="mt-1 text-safe-wrap text-sm leading-6 text-[#937D74]">{workspace.settlement?.settlement ? `目前有待結算差額 ${money(workspace.settlement.settlement.amount)}。` : "目前沒有待結算差額。"}</p></div>{workspace.settlement?.settlement && <Button type="button" size="sm" onClick={onSettle} className="shrink-0 rounded-xl bg-[#B56C78]">已結算</Button>}</section></div> }
function Overview({ workspace, ledger, month, setMonth, memberName, getCategory, onAdd, onEdit, onDelete, onSettle }: any) { const [copied, setCopied] = useState(false); const copy = async () => { try { await navigator.clipboard.writeText(ledger.inviteCode); setCopied(true); setTimeout(() => setCopied(false), 1000); } catch { toast.error("目前無法複製邀請碼。") } }; const transactions = workspace.calendarTransactions ?? []; return <div className="ledger-overview-stack space-y-6"><section className="ledger-hero rounded-[28px] bg-[#5B4142] p-6 text-white sm:p-8"><div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-xs font-semibold tracking-[0.16em] text-[#E8CBCD]">共同帳本</p><h2 className="mt-3 font-serif text-3xl">本月一起記下的日常</h2><p className="mt-2 text-sm text-[#E4D3D0]">所有收支、結算與設定皆與 Android App 共用。</p></div><div className="flex gap-2"><input type="month" value={month} onChange={event => setMonth(event.target.value)} className="min-w-0 flex-1 rounded-xl bg-white/10 px-3 py-2 text-sm [color-scheme:dark]" /><Button type="button" onClick={onAdd} className="shrink-0 rounded-xl bg-white text-[#9B5867]"><Plus size={16} className="mr-2" />新增收支</Button></div></div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Metric label="本月收入" value={money(workspace.analytics?.income)} tone="text-[#5E856A]" /><Metric label="本月支出" value={money(workspace.analytics?.expense)} tone="text-[#AD5D68]" /><Metric label="本月餘額" value={money(workspace.analytics?.balance)} tone="text-[#735D7A]" /></div><div className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><Card title="最近收支" text={`${month} 的即時帳本資料`}>{transactions.length ? <div className="divide-y divide-[#F1E7E2]">{transactions.slice(0, 6).map((item: any) => <TransactionRow key={item.id} item={item} category={getCategory(item.categoryId)} payer={memberName(item.payerId)} onEdit={() => onEdit(item)} onDelete={() => onDelete(item)} />)}</div> : <EmptyText text="這個月還沒有收支。" />}</Card><div className="space-y-5"><Card title="分類支出">{workspace.analytics?.categories?.length ? <div className="space-y-4">{workspace.analytics.categories.slice(0, 6).map((item: any) => <div key={item.id}><div className="flex justify-between text-sm"><span>{item.icon} {item.name}</span><b>{money(item.amount)}</b></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[#F1E7E2]"><div className="h-full rounded-full" style={{ width: `${Math.min(100, item.amount / Math.max(workspace.analytics.expense, 1) * 100)}%`, backgroundColor: item.color }} /></div></div>)}</div> : <EmptyText text="尚無可分析的支出。" />}</Card><Card title="帳本邀請與結算"><div className="flex items-center justify-between"><div><p className="font-mono text-xl font-bold tracking-[0.16em]">{ledger.inviteCode}</p><p className="mt-1 text-xs text-[#916F68]">網頁與 App 都可使用此邀請碼加入。</p></div><Button type="button" size="icon" variant="outline" onClick={() => void copy()}>{copied ? <Check size={16} /> : <Clipboard size={16} />}</Button></div>{workspace.settlement?.settlement ? <Button type="button" onClick={onSettle} className="mt-4 rounded-xl bg-[#B56C78]">標記已結算</Button> : <p className="mt-4 text-sm text-[#798E7D]">目前沒有待結算差額。</p>}</Card></div></div></div> }
function TransactionRow({ item, category, payer, onEdit }: any) { return <button type="button" onClick={onEdit} className="ledger-transaction-row flex w-full min-w-0 items-center gap-3 py-4 text-left transition-colors hover:bg-[#FCF7F4] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#B56C78] focus-visible:ring-offset-2"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl text-xl" style={{ color: category?.color || "#B56C78", backgroundColor: `${category?.color || "#B56C78"}18` }}>{categoryEmoji(category)}</span><span className="min-w-0 flex-1"><b className="block truncate text-base">{item.note || category?.name || "未命名收支"}</b><small className="mt-0.5 block truncate text-sm text-[#9A847B]">{day(item.date)} · {payer}</small></span><b className={`shrink-0 text-base ${item.type === "income" ? "text-[#598267]" : "text-[#AD5D68]"}`}>{item.type === "income" ? "+" : "−"}{money(item.amount)}</b></button> }
function Records({ workspace, getCategory, getPayment, memberName, onEdit, onDelete }: any) {
  const [range, setRange] = useState<"week" | "month" | "previous">("month");
  const periods = { week: "本週", month: "本月", previous: "上月" } as const;
  const transactions = useMemo(() => {
    const now = new Date();
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const previousStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const weekStart = new Date(now);
    weekStart.setHours(0, 0, 0, 0);
    weekStart.setDate(now.getDate() - ((now.getDay() + 6) % 7));
    return (workspace.transactions || []).filter((item: any) => {
      const date = new Date(item.date);
      if (Number.isNaN(date.getTime())) return false;
      if (range === "week") return date >= weekStart && date <= now;
      if (range === "previous") return date >= previousStart && date < monthStart;
      return date >= monthStart && date <= now;
    });
  }, [range, workspace.transactions]);
  const renderMobileRow = (item: any) => {
    const cat = getCategory(item.categoryId); const pay = getPayment(item.paymentMethodId);
    return <div key={item.id} className="flex min-w-0 items-center gap-3 py-3"><button type="button" onClick={() => onEdit(item)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl text-lg" style={{ color: cat?.color || "#B56C78", backgroundColor: `${cat?.color || "#B56C78"}18` }}>{categoryEmoji(cat)}</span><span className="min-w-0 flex-1"><b className="block truncate text-sm">{item.note || cat?.name || "未命名收支"}</b><small className="mt-1 block truncate text-xs text-[#9A847B]">{day(item.date)} · {memberName(item.payerId)} · {pay ? `${paymentEmoji(pay)} ${pay.name}` : "未指定"}</small></span><b className={`shrink-0 text-sm ${item.type === "income" ? "text-[#5D856A]" : "text-[#AA5F6A]"}`}>{item.type === "income" ? "+" : "−"}{money(item.amount)}</b></button><Button type="button" size="icon" variant="ghost" aria-label="刪除收支" onClick={() => onDelete(item)} className="h-9 w-9 shrink-0 text-[#B2606C]"><Trash2 size={16} /></Button></div>;
  };
  return <Card title="完整收支" text="以 Android App 相同的週期檢視、編輯與刪除流程管理收支。"><div className="mb-4 grid grid-cols-3 gap-2 rounded-2xl bg-[#F8F0EC] p-1.5">{(Object.keys(periods) as Array<keyof typeof periods>).map(key => <button key={key} type="button" onClick={() => setRange(key)} className={`min-h-10 rounded-xl px-2 text-sm font-semibold transition-colors ${range === key ? "bg-white text-[#A35F6D] shadow-sm" : "text-[#8F786F]"}`}>{periods[key]}</button>)}</div>{transactions.length ? <><div className="divide-y divide-[#F1E7E2] md:hidden">{transactions.map(renderMobileRow)}</div><div className="hidden overflow-x-auto md:block"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-b text-xs text-[#9A837A]"><tr><th className="p-3">日期／項目</th><th className="p-3">分類</th><th className="p-3">付款人</th><th className="p-3">支付方式</th><th className="p-3 text-right">金額</th><th className="p-3">操作</th></tr></thead><tbody>{transactions.map((item: any) => { const cat = getCategory(item.categoryId); const pay = getPayment(item.paymentMethodId); return <tr key={item.id} className="border-b border-[#F3EBE7]"><td className="p-3"><b>{item.note || cat?.name || "未命名收支"}</b><small className="mt-1 block text-[#A18A81]">{day(item.date)} · {item.type === "income" ? "收入" : item.type === "transfer" ? "轉帳" : "支出"}</small></td><td className="p-3">{categoryEmoji(cat)} {cat?.name || "未分類"}</td><td className="p-3">{memberName(item.payerId)}</td><td className="p-3">{pay ? `${paymentEmoji(pay)} ${pay.name}` : "未指定"}</td><td className={`p-3 text-right font-bold ${item.type === "income" ? "text-[#5D856A]" : "text-[#AA5F6A]"}`}>{item.type === "income" ? "+" : "−"}{money(item.amount)}</td><td className="p-3"><Button type="button" size="sm" variant="ghost" onClick={() => onEdit(item)}>編輯</Button><Button type="button" size="sm" variant="ghost" onClick={() => onDelete(item)} className="text-[#B2606C]">刪除</Button></td></tr> })}</tbody></table></div></> : <EmptyText text={`${periods[range]}沒有收支紀錄。`} />}</Card>;
}
function Calendar({ workspace, getCategory, memberName, onEdit }: any) { const groups = useMemo(() => (workspace.calendarTransactions || []).reduce((all: any, item: any) => { const key = new Date(item.date).toISOString().slice(0, 10); (all[key] ||= []).push(item); return all; }, {}), [workspace.calendarTransactions]); return <Card title="本月收支月曆" text="點選任一筆收支即可編輯。">{Object.keys(groups).length ? <div className="space-y-5">{Object.entries(groups).map(([key, items]: any) => <div key={key}><b className="text-sm text-[#855E62]">{day(`${key}T12:00:00`)}</b><div className="mt-2 grid gap-2 md:grid-cols-2">{items.map((item: any) => <button key={item.id} type="button" onClick={() => onEdit(item)} className="flex items-center justify-between rounded-2xl border border-[#EEE2DD] bg-[#FFFCFB] px-4 py-3 text-left"><span>{getCategory(item.categoryId)?.icon} {item.note || getCategory(item.categoryId)?.name || "未命名收支"}<small className="ml-2 text-[#9A847B]">{memberName(item.payerId)}</small></span><b className={item.type === "income" ? "text-[#5E856A]" : "text-[#AD5D68]"}>{item.type === "income" ? "+" : "−"}{money(item.amount)}</b></button>)}</div></div>)}</div> : <EmptyText text="本月尚無收支。" />}</Card> }
function AppCalendar({ workspace, month, setMonth, getCategory, memberName, onEdit }: any) {
  const [selected, setSelected] = useState(`${month}-01`);
  useEffect(() => setSelected(`${month}-01`), [month]);
  const [year, monthNumber] = month.split("-").map(Number);
  const firstDay = new Date(year, monthNumber - 1, 1).getDay();
  const daysInMonth = new Date(year, monthNumber, 0).getDate();
  const dayCells = Array.from({ length: Math.ceil((firstDay + daysInMonth) / 7) * 7 }, (_, index) => index < firstDay || index >= firstDay + daysInMonth ? null : index - firstDay + 1);
  const toLocalDateKey = (value: unknown) => {
    const date = new Date(value as string);
    return Number.isNaN(date.getTime()) ? "" : `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  };
  const transactions = workspace.calendarTransactions || [];
  const transactionsByDate = useMemo(() => transactions.reduce((all: Record<string, any[]>, item: any) => {
    const key = toLocalDateKey(item.date);
    if (key) (all[key] ||= []).push(item);
    return all;
  }, {}), [transactions]);
  const dayTotal = (dateKey: string) => (transactionsByDate[dateKey] || []).reduce((sum: number, item: any) => sum + (item.type === "expense" ? Number(item.amount || 0) : -Number(item.amount || 0)), 0);
  const changeMonth = (offset: number) => {
    const next = new Date(year, monthNumber - 1 + offset, 1);
    setMonth(`${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, "0")}`);
  };
  const selectedTransactions = transactionsByDate[selected] || [];
  return <div className="app-calendar-page space-y-4 sm:space-y-5">
    <section className="app-calendar-intro rounded-[28px] p-5 sm:p-7"><p className="text-xs font-bold tracking-[0.16em] text-[#5F93AB]">MONTHLY VIEW</p><div className="mt-3 flex items-center justify-between gap-3"><button type="button" onClick={() => changeMonth(-1)} aria-label="上個月" className="app-calendar-arrow"><ChevronLeft size={21} /></button><div className="min-w-0 text-center"><h2 className="text-safe-wrap text-2xl font-bold text-[#354E5D]">{year} 年 {monthNumber} 月</h2><p className="mt-1 text-sm text-[#748B97]">點選日期查看當天的收支明細。</p></div><button type="button" onClick={() => changeMonth(1)} aria-label="下個月" className="app-calendar-arrow"><ChevronRight size={21} /></button></div></section>
    <section className="app-calendar-card rounded-[28px] p-3.5 sm:p-5"><div className="grid grid-cols-7 gap-1 text-center text-xs font-semibold text-[#7491A0]">{["日", "一", "二", "三", "四", "五", "六"].map(weekday => <span key={weekday} className="py-1.5">{weekday}</span>)}</div><div className="mt-1 grid grid-cols-7 gap-1">{dayCells.map((date, index) => {
      if (!date) return <span key={`blank-${index}`} className="app-calendar-day app-calendar-blank" />;
      const dateKey = `${month}-${String(date).padStart(2, "0")}`;
      const total = dayTotal(dateKey);
      const hasTransactions = Boolean(transactionsByDate[dateKey]?.length);
      return <button key={dateKey} type="button" onClick={() => setSelected(dateKey)} aria-pressed={selected === dateKey} className={`app-calendar-day ${selected === dateKey ? "app-calendar-day-selected" : ""}`}><span>{date}</span>{hasTransactions && <i className={total > 0 ? "app-calendar-dot app-calendar-dot-expense" : "app-calendar-dot app-calendar-dot-income"} aria-label={total > 0 ? "當日支出" : "當日收入"} />}</button>;
    })}</div></section>
    <section className="app-calendar-card rounded-[28px] p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><h2 className="text-lg font-bold text-[#354E5D]">{selected.slice(5).replace("-", " / ")} 明細</h2><p className="mt-1 text-sm text-[#7A909B]">{selectedTransactions.length} 筆收支紀錄</p></div><CalendarDays size={24} className="text-[#5E91AA]" /></div>{selectedTransactions.length ? <div className="mt-4 divide-y divide-[#E4EEF0]">{selectedTransactions.map((item: any) => { const category = getCategory(item.categoryId); return <button key={item.id} type="button" onClick={() => onEdit(item)} className="flex w-full min-w-0 items-center gap-3 py-3 text-left"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl" style={{ color: category?.color || "#5E91AA", backgroundColor: `${category?.color || "#5E91AA"}18` }}>{categoryEmoji(category)}</span><span className="min-w-0 flex-1"><b className="block truncate text-sm text-[#3A5260]">{item.note || category?.name || "未命名收支"}</b><small className="mt-1 block truncate text-xs text-[#7C929D]">{memberName(item.payerId)}</small></span><b className={`shrink-0 text-sm ${item.type === "income" ? "text-[#5E856A]" : "text-[#AD5D68]"}`}>{item.type === "income" ? "+" : "−"}{money(item.amount)}</b></button>; })}</div> : <EmptyText text="這天還沒有收支記錄。" />}</section>
  </div>;
}

function Analysis({ workspace, month, setMonth }: any) {
  const expense = Number(workspace.analytics?.expense || 0); const prior = Number(workspace.previousAnalytics?.expense || 0); const difference = expense - prior;
  const categories = workspace.analytics?.categories || [];
  let cursor = 0;
  const gradient = categories.length ? `conic-gradient(${categories.map((item: any) => { const start = cursor; cursor += Number(item.amount || 0) / Math.max(expense, 1) * 100; return `${item.color || "#B56C78"} ${start}% ${cursor}%`; }).join(", ")})` : "conic-gradient(#F0E7E2 0 100%)";
  const trendPercent = prior ? Math.round(Math.abs(difference) / prior * 100) : null;
  return <div className="space-y-5"><Card title="帳本分析" text="依月份比較收支與分類占比。"><div className="flex justify-end"><input type="month" value={month} onChange={event => setMonth(event.target.value)} className="rounded-xl border border-[#DDC7C0] bg-white px-3 py-2 text-sm" /></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><Metric label="本月支出" value={money(expense)} tone="text-[#AD5D68]" /><Metric label="上月支出" value={money(prior)} tone="text-[#735D7A]" /><Metric label="支出變化" value={`${difference >= 0 ? "+" : ""}${money(difference)}`} tone={difference > 0 ? "text-[#AD5D68]" : "text-[#5D856A]"} /></div></Card><div className="grid gap-5 lg:grid-cols-[0.8fr_1.2fr]"><Card title="分類圓環" text="本月支出比例">{categories.length ? <div className="flex items-center justify-center py-2"><div className="relative h-44 w-44 rounded-full" style={{ background: gradient }}><div className="absolute inset-[28px] flex flex-col items-center justify-center rounded-full bg-[var(--card)] text-center"><span className="text-xs text-[#967E75]">本月支出</span><b className="mt-1 text-sm text-[#705B53]">{money(expense)}</b></div></div></div> : <EmptyText text="尚無資料可分析。" />}</Card><Card title="分類金額" text="依支出金額由高至低呈現。">{categories.length ? <div className="space-y-4">{categories.map((item: any) => <div key={item.id}><div className="flex min-w-0 justify-between gap-3 text-sm"><span className="min-w-0 truncate">{categoryEmoji(item)} {item.name}</span><span className="shrink-0"><b>{money(item.amount)}</b> · {Math.round(Number(item.amount || 0) / Math.max(expense, 1) * 100)}%</span></div><div className="mt-2 h-3 overflow-hidden rounded-full bg-[#F0E7E2]"><div className="h-full rounded-full" style={{ width: `${Math.min(100, Number(item.amount || 0) / Math.max(expense, 1) * 100)}%`, backgroundColor: item.color }} /></div></div>)}</div> : <EmptyText text="尚無資料可分析。" />}</Card></div><Card title="與上月比較" text="以同一帳本的上個月支出作為比較基準。"><div className="grid items-center gap-4 sm:grid-cols-[1fr_auto_1fr]"><div className="rounded-2xl bg-[#F8F0EC] p-4"><p className="text-xs text-[#967E75]">上月支出</p><b className="mt-1 block text-xl text-[#735D7A]">{money(prior)}</b></div><div className={`rounded-full px-3 py-2 text-center text-sm font-bold ${difference > 0 ? "bg-[#FBECEE] text-[#AD5D68]" : "bg-[#EDF5EF] text-[#5D856A]"}`}>{trendPercent === null ? "首次比較" : `${difference > 0 ? "增加" : difference < 0 ? "減少" : "持平"} ${trendPercent}%`}</div><div className="rounded-2xl bg-[#F8F0EC] p-4"><p className="text-xs text-[#967E75]">本月支出</p><b className="mt-1 block text-xl text-[#AD5D68]">{money(expense)}</b></div></div></Card></div>;
}
function Planning({ workspace, getCategory, getPayment, onBudget, onTotalBudget, onRecurring, onEditRecurring, onTravel, onSync, onDeleteBudget, onDeleteRecurring, onDeleteTravel }: any) {
  const totalBudget = (workspace.budgets || []).find((item: any) => Number(item.categoryId) === 0);
  const total = Number(totalBudget?.amount || 0); const spent = Number(workspace.analytics?.expense || 0); const percent = total ? Math.min(100, Math.round(spent / total * 100)) : 0; const remaining = Math.max(0, total - spent);
  const categoryBudgets = (workspace.budgets || []).filter((item: any) => Number(item.categoryId) !== 0);
  return <div className="grid gap-5 xl:grid-cols-2"><Card title="月總預算" text="總預算與分類預算會同步到 Android App。"><div className="rounded-2xl bg-[#FBF2EE] p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-sm text-[#967E75]">本月已使用</p><b className="mt-1 block text-2xl text-[#AD5D68]">{money(spent)}</b><p className="mt-1 text-xs text-[#9A847B]">{total ? `／ ${money(total)} · ${percent}%` : "尚未設定總預算"}</p></div><Button type="button" size="sm" variant="outline" onClick={onTotalBudget} className="shrink-0 rounded-xl border-[#DDBFB7] bg-white text-[#9A5C67]">{total ? "調整" : "設定"}</Button></div><div className="mt-5 h-3 overflow-hidden rounded-full bg-[#EFDCD5]"><div className={`h-full rounded-full ${total && spent > total ? "bg-[#C35F68]" : "bg-[#B56C78]"}`} style={{ width: `${percent}%` }} /></div><p className={`mt-3 text-sm ${total && spent > total ? "text-[#B35360]" : "text-[#75886F]"}`}>{total ? spent > total ? `已超出 ${money(spent - total)}` : `還可使用 ${money(remaining)}` : "設定後即可追蹤本月使用進度。"}</p></div></Card><Card title="分類預算" text="設定每月預算並和 App 共用。"><Button type="button" onClick={onBudget} className="mb-4 rounded-xl bg-[#B56C78]"><Plus size={15} className="mr-1" />設定預算</Button><List items={categoryBudgets.map((item: any) => ({ id: item.id, title: `${categoryEmoji(getCategory(item.categoryId))} ${getCategory(item.categoryId)?.name || "未分類"}`, detail: money(item.amount), remove: () => onDeleteBudget(item.id) }))} empty="尚未設定分類預算。" /></Card><Card title="固定收支" text="週期性收支可與 Android App 共用。"><div className="mb-4 flex flex-wrap gap-2"><Button type="button" onClick={onRecurring} className="rounded-xl bg-[#B56C78]"><Plus size={15} className="mr-1" />新增固定收支</Button><Button type="button" variant="outline" onClick={onSync}>同步到期項目</Button></div><List items={(workspace.recurring || []).map((item: any) => ({ id: item.id, title: item.title, detail: `${item.frequency === "weekly" ? "每週" : item.frequency === "yearly" ? "每年" : "每月"} · ${money(item.amount)} · ${categoryEmoji(getCategory(item.categoryId))} ${getPayment(item.paymentMethodId)?.name || "未指定"}`, edit: () => onEditRecurring(item), remove: () => onDeleteRecurring(item.id) }))} empty="尚未建立固定收支。" /></Card><Card title="出遊規劃" text="旅遊預算不會納入每月分類預算。"><Button type="button" onClick={onTravel} className="mb-4 rounded-xl bg-[#B56C78]"><Plus size={15} className="mr-1" />新增出遊規劃</Button><List items={(workspace.travelPlans || []).map((item: any) => ({ id: item.id, title: item.name, detail: `${money(item.budget)} · ${new Date(item.startDate).toLocaleDateString("zh-TW")} 至 ${new Date(item.endDate).toLocaleDateString("zh-TW")}${item.notes ? ` · ${item.notes}` : ""}`, remove: () => onDeleteTravel(item.id) }))} empty="尚未建立出遊規劃。" /></Card><Card title="結算紀錄" text="完成結算後會保留歷程。"><List items={(workspace.settlementHistory || []).map((item: any) => ({ id: item.id, title: `${item.month} 已結算`, detail: money(item.amount) }))} empty="尚無結算紀錄。" /></Card></div>;
}
function List({ items, empty }: { items: any[]; empty: string }) { return items.length ? <div className="divide-y divide-[#F0E7E2]">{items.map(item => <div key={item.id} className="flex gap-3 py-3"><div className="min-w-0 flex-1"><b className="block truncate text-sm">{item.title}</b><small className="mt-1 block text-[#927C74]">{item.detail}</small></div>{item.edit && <Button type="button" variant="ghost" size="sm" onClick={item.edit}>編輯</Button>}{item.remove && <Button type="button" variant="ghost" size="sm" onClick={item.remove} className="text-[#B2606C]">刪除</Button>}</div>)}</div> : <EmptyText text={empty} /> }
function LedgerSettings({ workspace, ledger, userId, memberName, onManage, onEditCategory, onEditPayment, onArchiveCategory, onRestoreCategory, onDeleteCategory, onArchivePayment, onRestorePayment, onDeletePayment, onRole, onLeave }: any) {
  const [logFilter, setLogFilter] = useState<"all" | "transaction" | "settings" | "member">("all");
  const logType = (log: any) => log.entityType === "transaction" ? "transaction" : log.entityType === "member" || log.entityType === "invite" ? "member" : "settings";
  const allLogs = (workspace.activityLogs || []).map((item: any) => item.log ?? item);
  const filteredLogs = logFilter === "all" ? allLogs : allLogs.filter((log: any) => logType(log) === logFilter);
  return <div className="grid gap-5 xl:grid-cols-2"><Card title="帳本與成員" text="管理名稱、權限與帳本成員。"><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" onClick={onManage}>修改名稱／轉讓</Button><Button type="button" variant="outline" onClick={() => navigator.clipboard.writeText(ledger.inviteCode).then(() => toast.success("邀請碼已複製。"))}>複製邀請碼</Button><Button type="button" variant="outline" onClick={() => onLeave("leave")}>退出帳本</Button><Button type="button" variant="ghost" className="text-[#B2606C]" onClick={() => onLeave("delete")}>刪除帳本</Button></div><div className="mt-5 divide-y divide-[#F0E7E2]">{(workspace.members || []).map((item: any) => <div key={item.member.userId} className="flex min-w-0 items-center gap-3 py-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#F5E6E6] text-[#A35F6D]"><Users size={15} /></span><span className="min-w-0 flex-1"><b className="block truncate text-sm">{item.user.name || "帳本成員"}</b><small className="block truncate text-[#9A847B]">{item.user.email}</small></span><select value={item.member.role} disabled={item.member.userId === userId} onChange={event => onRole(item.member.userId, event.target.value)} className="shrink-0 rounded-lg border border-[#DDC7C0] bg-white px-2 py-1 text-xs"><option value="admin">管理員</option><option value="member">成員</option><option value="viewer">檢視者</option></select></div>)}</div></Card><EntityList title="分類管理" text="新增、編輯、隱藏、恢復或永久刪除分類。" items={workspace.categories || []} onAdd={() => onEditCategory()} onEdit={onEditCategory} onArchive={onArchiveCategory} onRestore={onRestoreCategory} onRemove={onDeleteCategory} /><EntityList title="支付方式管理" text="支付方式會同步至交易、固定收支與 Android App。" items={workspace.paymentMethods || []} onAdd={() => onEditPayment()} onEdit={onEditPayment} onArchive={onArchivePayment} onRestore={onRestorePayment} onRemove={onDeletePayment} /><Card title="操作日誌" text="可依收支、設定或成員異動縮小紀錄範圍。"><div className="mb-4 grid grid-cols-4 gap-1 rounded-xl bg-[#F8F0EC] p-1">{([ ["all", "全部"], ["transaction", "收支"], ["settings", "設定"], ["member", "成員"] ] as const).map(([key, label]) => <button key={key} type="button" onClick={() => setLogFilter(key)} className={`min-h-9 rounded-lg px-1 text-xs font-semibold ${logFilter === key ? "bg-white text-[#A35F6D] shadow-sm" : "text-[#937C73]"}`}>{label}</button>)}</div>{filteredLogs.length ? <div className="max-h-80 divide-y divide-[#F0E7E2] overflow-y-auto pr-1">{filteredLogs.map((log: any) => <div key={log.id} className="flex min-w-0 gap-3 py-3"><span className="ledger-activity-icon flex h-9 w-9 shrink-0 items-center justify-center rounded-xl"><Sparkles size={15} /></span><div className="min-w-0"><b className="block text-safe-wrap text-sm">{log.summary || `${log.action || "帳本"} ${log.entityType || "異動"}`}</b><small className="mt-1 block text-safe-wrap text-[#9A847B]">{memberName(log.userId)} · {formatActivityTimestamp(log.createdAt)}</small><span className="mt-1 inline-block rounded-full bg-[#F8EFEC] px-2 py-0.5 text-[10px] font-medium text-[#9A6570]">{logType(log) === "transaction" ? "收支" : logType(log) === "member" ? "成員與邀請" : "帳本設定"}</span></div></div>)}</div> : <EmptyText text={logFilter === "all" ? "尚無操作日誌。" : "此類型尚無操作日誌。"} />}</Card></div>;
}
function EntityList({ title, text, items, onAdd, onEdit, onArchive, onRestore, onRemove }: any) { return <Card title={title} text={text}><Button type="button" onClick={onAdd} className="mb-4 rounded-xl bg-[#B56C78]"><Plus size={15} className="mr-1" />新增</Button><div className="max-h-[360px] divide-y divide-[#F0E7E2] overflow-y-auto">{items.map((item: any) => <div key={item.id} className="flex items-center gap-3 py-3"><span className="text-lg">{item.icon}</span><span className="min-w-0 flex-1"><b className="block text-sm">{item.name}</b><small className="text-[#9A847B]">{item.isActive ? "使用中" : "已隱藏"}</small></span><Button type="button" size="sm" variant="ghost" onClick={() => onEdit(item)}>編輯</Button>{item.isActive ? <Button type="button" size="sm" variant="ghost" onClick={() => onArchive(item.id)}>隱藏</Button> : <Button type="button" size="sm" variant="ghost" onClick={() => onRestore(item.id)}>恢復</Button>}<Button type="button" size="sm" variant="ghost" onClick={() => onRemove(item.id)} className="text-[#B2606C]">刪除</Button></div>)}</div></Card> }
function Profile({ workspace, onRefresh }: any) { const [, navigate] = useLocation(); const { user, logout } = useAuth(); const [name, setName] = useState(user?.name || ""); const [password, setPassword] = useState(""); const pref = trpc.notifications.preferences.useQuery(undefined, { refetchOnWindowFocus: false }); const updateName = trpc.profile.updateName.useMutation({ onSuccess: () => { toast.success("暱稱已儲存。 "); onRefresh(); }, onError: fail }); const updatePrefs = trpc.notifications.updatePreferences.useMutation({ onSuccess: () => toast.success("提醒設定已儲存。"), onError: fail }); const deleteAccount = trpc.auth.deleteAccount.useMutation({ onSuccess: async () => { await logout(); navigate("/"); }, onError: fail }); const leave = async () => { if (!window.confirm("確定要登出此裝置嗎？")) return; await logout(); navigate("/"); }; return <div className="grid gap-5 xl:grid-cols-2"><Card title="個人資料" text="暱稱會在所有共同帳本與 Android App 顯示。"><form className="flex flex-col gap-2 sm:flex-row" onSubmit={event => { event.preventDefault(); updateName.mutate({ name: name.trim() } as any); }}><Input value={name} onChange={event => setName(event.target.value)} required maxLength={64} /><Button type="submit" className="bg-[#B56C78]">儲存暱稱</Button></form></Card><Card title="通知與每月結算提醒" text="與 Android App 使用同一份提醒偏好設定。">{pref.data ? <form className="space-y-4" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); updatePrefs.mutate({ incomeEnabled: form.get("income") === "on", expenseEnabled: form.get("expense") === "on", minimumAmount: Number(form.get("minimum") || 0), monthlySettlementEnabled: form.get("monthly") === "on", monthlyReminderDay: Number(form.get("day") || 1) } as any); }}><CheckBox label="收入通知" name="income" checked={Boolean((pref.data as any).incomeEnabled)} /><CheckBox label="支出通知" name="expense" checked={Boolean((pref.data as any).expenseEnabled)} /><CheckBox label="每月結算提醒" name="monthly" checked={Boolean((pref.data as any).monthlySettlementEnabled)} /><div className="grid grid-cols-2 gap-3"><Field label="提醒門檻（元）"><Input name="minimum" type="number" min="0" defaultValue={(pref.data as any).minimumAmount} /></Field><Field label="每月提醒日"><Input name="day" type="number" min="1" max="28" defaultValue={(pref.data as any).monthlyReminderDay} /></Field></div><Button type="submit" className="bg-[#B56C78]">儲存提醒設定</Button></form> : <EmptyText text="正在讀取提醒設定…" />}</Card><Card title="更新與帳號安全" text={`目前網頁版本 ${APP_VERSION}；Android App 可從下方下載。`}><div className="space-y-4"><a href="https://github.com/ben880320-boop/together-ledger/releases" target="_blank" rel="noreferrer" className="inline-flex rounded-xl border border-[#DDC7C0] bg-white px-4 py-2 text-sm font-medium text-[#875A61]">查看版本更新歷程</a><form className="border-t border-[#F0E7E2] pt-4" onSubmit={event => { event.preventDefault(); if (window.confirm("確定要永久刪除帳號嗎？此動作不可復原。")) deleteAccount.mutate({ password } as any); }}><Label>刪除帳號前請輸入密碼</Label><div className="mt-2 flex flex-col gap-2 sm:flex-row"><Input type="password" value={password} onChange={event => setPassword(event.target.value)} required /><Button type="submit" variant="destructive">刪除帳號</Button></div></form></div></Card><Card title="Android App 與登入" text="使用官方 GitHub Release 下載 APK；登出不會刪除共同帳本資料。"><div className="flex flex-col gap-3 sm:flex-row"><a href="https://github.com/ben880320-boop/together-ledger/releases/latest" target="_blank" rel="noreferrer" className="inline-flex min-h-11 flex-1 items-center justify-center rounded-xl bg-[#B56C78] px-4 py-2 text-sm font-semibold text-white"><Download size={16} className="mr-2" />下載 Together Ledger App</a><Button type="button" variant="outline" onClick={() => void leave()} className="min-h-11 border-[#DDC7C0] text-[#875A61]"><LogOut size={16} className="mr-2" />登出</Button></div></Card></div> }
function CheckBox({ label, name, checked }: { label: string; name: string; checked: boolean }) { return <label className="flex items-center justify-between text-sm"><span>{label}</span><input name={name} type="checkbox" defaultChecked={checked} className="h-4 w-4 accent-[#B56C78]" /></label> }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block space-y-1.5"><span className="text-sm font-medium">{label}</span>{children}</label> }
function TextDialog({ open, title, description, label, submit, onClose, onSubmit }: any) { const [value, setValue] = useState(""); useEffect(() => { if (open) setValue(""); }, [open]); return <Dialog open={open} onOpenChange={next => !next && onClose()}><DialogContent className="rounded-3xl"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{description}</DialogDescription></DialogHeader><form className="mt-3 space-y-4" onSubmit={event => { event.preventDefault(); onSubmit(value.trim()); }}><Field label={label}><Input value={value} onChange={event => setValue(event.target.value)} required /></Field><Button type="submit" className="w-full bg-[#B56C78]">{submit}</Button></form></DialogContent></Dialog> }
function CreateLedgerDialog({ open, onClose, onSubmit }: { open: boolean; onClose: () => void; onSubmit: (input: { name: string; type: "couple"; icon?: string }) => void }) {
  const [name, setName] = useState(""); const [icon, setIcon] = useState<string | null>(null);
  const icons = ["❤", "💖", "🩷", "💘", "🌷", "🌹", "🚗", "📱", "💳", "💵", "🛍️", "📑", "🗓️", "📒", "📕", "📖", "📝", "🏠", "✈️", "🎯", "🐾", "🍽️", "🎮", "🎬", "✨"];
  useEffect(() => { if (open) { setName(""); setIcon(null); } }, [open]);
  return <Dialog open={open} onOpenChange={next => !next && onClose()}><DialogContent className="max-h-[88vh] overflow-y-auto rounded-3xl sm:max-w-lg"><DialogHeader><DialogTitle>建立新的共同帳本</DialogTitle><DialogDescription>為完全空白的新帳本命名，並可選擇一個方便辨識的圖示。</DialogDescription></DialogHeader><form className="mt-3 space-y-5" onSubmit={event => { event.preventDefault(); onSubmit({ name: name.trim(), type: "couple", ...(icon ? { icon } : {}) }); }}><Field label="帳本圖示（可選）"><div className="grid grid-cols-6 gap-2"><button type="button" onClick={() => setIcon(null)} className={`flex h-11 items-center justify-center rounded-xl border text-xs font-medium transition-colors ${icon === null ? "border-[#C77B88] bg-[#FBF0F1] text-[#9E5867]" : "border-[#E7D9D3] bg-white text-[#77645C]"}`} aria-pressed={icon === null}>無</button>{icons.map(item => <button key={item} type="button" onClick={() => setIcon(item)} className={`flex h-11 items-center justify-center rounded-xl border text-xl transition-colors ${icon === item ? "border-[#C77B88] bg-[#FBF0F1]" : "border-[#E7D9D3] bg-white hover:bg-[#FFF7F4]"}`} aria-label={`使用 ${item} 作為帳本圖示`} aria-pressed={icon === item}>{item}</button>)}</div></Field><Field label="帳本名稱"><Input value={name} onChange={event => setName(event.target.value)} maxLength={60} placeholder="例如：我們的生活帳本" required /></Field><Button type="submit" className="w-full bg-[#B56C78]">建立空白帳本</Button></form></DialogContent></Dialog>;
}
function TransactionDialog({ open, workspace, ledgerId, editing, onClose, onCreate, onUpdate }: any) { const [type, setType] = useState("expense"); const [note, setNote] = useState(""); const [amount, setAmount] = useState(""); const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [categoryId, setCategoryId] = useState(0); const [paymentId, setPaymentId] = useState(0); const [payerId, setPayerId] = useState(0); const [split, setSplit] = useState("equal"); const [shares, setShares] = useState<Record<number, string>>({}); const scan = trpc.ledger.scanReceipt.useMutation({ onSuccess: (item: any) => { if (item.amount) setAmount(String(item.amount)); if (item.note) setNote(item.note); if (item.date) setDate(item.date); toast.success("已填入可辨識的發票欄位，請確認後儲存。") }, onError: fail }); useEffect(() => { if (!open || !workspace) return; const item = editing; const next = item?.type || "expense"; setType(next); setNote(item?.note || ""); setAmount(item ? String(item.amount) : ""); setDate(item ? new Date(item.date).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10)); setCategoryId(item?.categoryId || workspace.categories?.find((x: any) => x.type === next && x.isActive)?.id || 0); setPaymentId(item?.paymentMethodId || workspace.paymentMethods?.find((x: any) => x.isActive)?.id || 0); setPayerId(item?.payerId || workspace.members?.[0]?.member.userId || 0); setSplit(item?.splitType || (next === "expense" ? "equal" : "none")); setShares({}); }, [open, editing, workspace]); if (!workspace) return null; const categories = workspace.categories?.filter((item: any) => item.isActive && item.type === type) || []; const methods = workspace.paymentMethods?.filter((item: any) => item.isActive) || []; const submit = (event: FormEvent) => { event.preventDefault(); const total = Math.round(Number(amount)); if (!total || !categoryId || !paymentId || !payerId) return toast.error("請完整填寫收支資訊。"); const members = workspace.members || []; const splits = type === "expense" && split !== "none" ? members.map((item: any, index: number) => ({ userId: item.member.userId, shareAmount: split === "equal" ? (index === members.length - 1 ? total - Math.floor(total / members.length) * index : Math.floor(total / members.length)) : Math.round(Number(shares[item.member.userId] || 0)) })) : []; if (split === "custom" && splits.reduce((sum: number, item: any) => sum + item.shareAmount, 0) !== total) return toast.error("分攤金額必須剛好等於總金額。"); const input = { ledgerId, payerId, amount: total, type, categoryId, paymentMethodId: paymentId, date: new Date(`${date}T12:00:00`), note: note.trim() || undefined, splitType: type === "expense" ? split : "none", splits }; editing ? onUpdate({ ...input, transactionId: editing.id }) : onCreate(input); }; const readReceipt = (file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => scan.mutate({ imageDataUrl: String(reader.result) } as any); reader.readAsDataURL(file); }; return <Dialog open={open} onOpenChange={next => !next && onClose()}><DialogContent className="max-h-[88vh] overflow-y-auto rounded-3xl sm:max-w-lg"><DialogHeader><DialogTitle>{editing ? "編輯收支" : "新增收支"}</DialogTitle><DialogDescription>使用與 Android App 相同的分類、支付方式、付款人與分攤規則。</DialogDescription></DialogHeader><form className="mt-3 space-y-4" onSubmit={submit}><div className="grid grid-cols-3 gap-2">{["expense", "income", "transfer"].map(item => <Button key={item} type="button" variant={type === item ? "default" : "outline"} onClick={() => { setType(item); setCategoryId(workspace.categories?.find((x: any) => x.type === item && x.isActive)?.id || 0); setSplit(item === "expense" ? "equal" : "none"); }} className={type === item ? "bg-[#B56C78]" : ""}>{item === "expense" ? "支出" : item === "income" ? "收入" : "轉帳"}</Button>)}</div><Field label="發票掃描（選填）"><Input type="file" accept="image/*" capture="environment" onChange={event => readReceipt(event.target.files?.[0])} /></Field><div className="grid grid-cols-2 gap-3"><Field label="金額"><Input type="number" min="1" value={amount} onChange={event => setAmount(event.target.value)} required /></Field><Field label="日期"><Input type="date" value={date} onChange={event => setDate(event.target.value)} required /></Field></div><Field label="項目／備註"><Textarea value={note} onChange={event => setNote(event.target.value)} maxLength={500} /></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="分類"><select value={categoryId} onChange={event => setCategoryId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{categories.map((item: any) => <option key={item.id} value={item.id}>{item.icon} {item.name}</option>)}</select></Field><Field label="支付方式"><select value={paymentId} onChange={event => setPaymentId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{methods.map((item: any) => <option key={item.id} value={item.id}>{item.icon} {item.name}</option>)}</select></Field><Field label="付款人"><select value={payerId} onChange={event => setPayerId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{workspace.members?.map((item: any) => <option key={item.member.userId} value={item.member.userId}>{item.user.name}</option>)}</select></Field></div>{type === "expense" && <div className="rounded-2xl bg-[#F9F1EE] p-4"><Label>分攤方式</Label><div className="mt-2 flex flex-wrap gap-2">{[["equal", "平均分攤"], ["custom", "自訂金額"], ["none", "不分攤"]].map(([value, text]) => <Button key={value} type="button" size="sm" variant={split === value ? "default" : "outline"} onClick={() => setSplit(value)} className={split === value ? "bg-[#B56C78]" : ""}>{text}</Button>)}</div>{split === "custom" && <div className="mt-3 grid gap-2 sm:grid-cols-2">{workspace.members?.map((item: any) => <Field key={item.member.userId} label={item.user.name}><Input type="number" min="0" value={shares[item.member.userId] || ""} onChange={event => setShares(old => ({ ...old, [item.member.userId]: event.target.value }))} /></Field>)}</div>}</div>}<Button type="submit" className="w-full bg-[#B56C78]">{editing ? "儲存修改" : "新增收支"}</Button></form></DialogContent></Dialog> }
function BudgetDialog({ open, totalBudget = false, workspace, ledgerId, month, onClose, onSave }: any) { const [categoryId, setCategoryId] = useState(0); const [amount, setAmount] = useState(""); useEffect(() => { if (open) { const total = workspace?.budgets?.find((item: any) => Number(item.categoryId) === 0); setCategoryId(totalBudget ? 0 : workspace?.categories?.find((item: any) => item.isActive && item.type === "expense")?.id || 0); setAmount(totalBudget && total ? String(total.amount) : ""); } }, [open, totalBudget, workspace]); return <SimpleForm open={open} title={totalBudget ? "設定月總預算" : "設定分類預算"} onClose={onClose} onSubmit={() => onSave({ ledgerId, categoryId, amount: Math.round(Number(amount)), month })}>{totalBudget ? <p className="rounded-2xl bg-[#FBF2EE] p-4 text-sm leading-6 text-[#866E65]">月總預算會顯示本月全部支出的使用進度；分類預算可另外設定。</p> : <Field label="分類"><select value={categoryId} onChange={event => setCategoryId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{workspace?.categories?.filter((item: any) => item.isActive && item.type === "expense").map((item: any) => <option key={item.id} value={item.id}>{categoryEmoji(item)} {item.name}</option>)}</select></Field>}<Field label="預算金額"><Input type="number" min="1" value={amount} onChange={event => setAmount(event.target.value)} required /></Field></SimpleForm> }
function RecurringDialog({ open, workspace, ledgerId, editing, onClose, onSave }: any) { const [title, setTitle] = useState(""); const [amount, setAmount] = useState(""); const [categoryId, setCategoryId] = useState(0); const [paymentMethodId, setPaymentMethodId] = useState(0); const [frequency, setFrequency] = useState("monthly"); const [dayOfMonth, setDayOfMonth] = useState(1); useEffect(() => { if (open) { setTitle(editing?.title || ""); setAmount(editing?.amount ? String(editing.amount) : ""); setCategoryId(editing?.categoryId || workspace?.categories?.find((item: any) => item.isActive && item.type === "expense")?.id || 0); setPaymentMethodId(editing?.paymentMethodId || workspace?.paymentMethods?.find((item: any) => item.isActive)?.id || 0); setFrequency(editing?.frequency || "monthly"); setDayOfMonth(editing?.dayOfMonth || 1); } }, [open, editing, workspace]); return <SimpleForm open={open} title={editing ? "編輯固定收支" : "新增固定收支"} onClose={onClose} onSubmit={() => onSave({ ledgerId, ...(editing ? { recurringId: editing.id } : {}), title, amount: Math.round(Number(amount)), type: "expense", categoryId, paymentMethodId, frequency, dayOfMonth })}><Field label="名稱"><Input value={title} onChange={event => setTitle(event.target.value)} required /></Field><div className="grid grid-cols-2 gap-3"><Field label="金額"><Input type="number" min="1" value={amount} onChange={event => setAmount(event.target.value)} required /></Field><Field label="週期"><select value={frequency} onChange={event => setFrequency(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3"><option value="weekly">每週</option><option value="monthly">每月</option><option value="yearly">每年</option></select></Field></div><Field label="扣款日"><Input type="number" min="1" max="31" value={dayOfMonth} onChange={event => setDayOfMonth(Number(event.target.value))} required /></Field><Field label="分類"><select value={categoryId} onChange={event => setCategoryId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{workspace?.categories?.filter((item: any) => item.isActive && item.type === "expense").map((item: any) => <option key={item.id} value={item.id}>{item.icon} {item.name}</option>)}</select></Field><Field label="支付方式"><select value={paymentMethodId} onChange={event => setPaymentMethodId(Number(event.target.value))} className="h-10 w-full rounded-md border border-input bg-background px-3">{workspace?.paymentMethods?.filter((item: any) => item.isActive).map((item: any) => <option key={item.id} value={item.id}>{item.icon} {item.name}</option>)}</select></Field></SimpleForm> }
function TravelDialog({ open, ledgerId, onClose, onSave }: any) { const [name, setName] = useState(""); const [budget, setBudget] = useState(""); const [startDate, setStart] = useState(new Date().toISOString().slice(0, 10)); const [endDate, setEnd] = useState(new Date().toISOString().slice(0, 10)); const [notes, setNotes] = useState(""); return <SimpleForm open={open} title="新增出遊規劃" onClose={onClose} onSubmit={() => onSave({ ledgerId, name, budget: Math.round(Number(budget)), startDate: new Date(`${startDate}T12:00:00`), endDate: new Date(`${endDate}T12:00:00`), notes: notes || undefined })}><Field label="行程名稱"><Input value={name} onChange={event => setName(event.target.value)} required /></Field><Field label="出遊預算"><Input type="number" min="1" value={budget} onChange={event => setBudget(event.target.value)} required /></Field><div className="grid grid-cols-2 gap-3"><Field label="開始日期"><Input type="date" value={startDate} onChange={event => setStart(event.target.value)} /></Field><Field label="結束日期"><Input type="date" value={endDate} onChange={event => setEnd(event.target.value)} /></Field></div><Field label="備註"><Textarea value={notes} onChange={event => setNotes(event.target.value)} /></Field></SimpleForm> }
function EntityDialog({ open, type, ledgerId, entity, onClose, onCategory, onPayment }: any) { const [name, setName] = useState(""); const [icon, setIcon] = useState("🍜"); const [categoryType, setCategoryType] = useState("expense"); useEffect(() => { if (open) { setName(entity?.name || ""); setIcon(type === "payment" ? paymentEmoji(entity) : categoryEmoji(entity)); setCategoryType(entity?.type || "expense"); } }, [open, entity, type]); const submit = () => { if (type === "category") { const input = { ledgerId, name, icon: categoryEmoji({ name, icon }), type: categoryType, color: "#B56C78", parentCategoryId: 0 }; onCategory(entity ? { ...input, categoryId: entity.id } : input); } else { const input = { ledgerId, name, icon: paymentEmoji({ name, icon }) }; onPayment(entity ? { ...input, paymentMethodId: entity.id } : input); } }; return <SimpleForm open={open} title={`${entity ? "編輯" : "新增"}${type === "category" ? "分類" : "支付方式"}`} onClose={onClose} onSubmit={submit}><Field label="名稱"><Input value={name} onChange={event => setName(event.target.value)} required /></Field><Field label="圖示"><div className="flex flex-wrap gap-2">{iconOptions.map(value => <button key={value} type="button" onClick={() => setIcon(value)} className={`rounded-lg border px-2 py-1.5 ${icon === value ? "border-[#B56C78] bg-[#F7E8E8]" : "border-[#E5D8D2]"}`}>{value}</button>)}</div></Field>{type === "category" && <Field label="類型"><select value={categoryType} onChange={event => setCategoryType(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3"><option value="expense">支出分類</option><option value="income">收入分類</option></select></Field>}</SimpleForm> }
function ManageDialog({ open, ledger, workspace, userId, onClose, onRename, onTransfer }: any) { const [name, setName] = useState(""); const [target, setTarget] = useState(0); useEffect(() => { if (open) { setName(ledger?.name || ""); setTarget(workspace?.members?.find((item: any) => item.member.userId !== userId)?.member.userId || 0); } }, [open, ledger, workspace, userId]); return <Dialog open={open} onOpenChange={next => !next && onClose()}><DialogContent className="rounded-3xl"><DialogHeader><DialogTitle>帳本管理</DialogTitle><DialogDescription>可修改帳本名稱或將持有權轉讓給其他成員。</DialogDescription></DialogHeader><div className="mt-4 space-y-5"><form className="flex gap-2" onSubmit={event => { event.preventDefault(); onRename(name); }}><Input value={name} onChange={event => setName(event.target.value)} required /><Button type="submit" className="bg-[#B56C78]">儲存名稱</Button></form><div className="border-t pt-4"><Label>轉讓帳本持有權</Label><div className="mt-2 flex gap-2"><select value={target} onChange={event => setTarget(Number(event.target.value))} className="h-10 min-w-0 flex-1 rounded-md border border-input bg-background px-3">{workspace?.members?.filter((item: any) => item.member.userId !== userId).map((item: any) => <option key={item.member.userId} value={item.member.userId}>{item.user.name}</option>)}</select><Button type="button" variant="outline" onClick={() => target && onTransfer(target)}>轉讓</Button></div></div></div></DialogContent></Dialog> }
function SimpleForm({ open, title, onClose, onSubmit, children }: any) { return <Dialog open={open} onOpenChange={next => !next && onClose()}><DialogContent className="max-h-[88vh] overflow-y-auto rounded-3xl sm:max-w-md"><DialogHeader><DialogTitle>{title}</DialogTitle></DialogHeader><form className="mt-3 space-y-4" onSubmit={event => { event.preventDefault(); onSubmit(); }}>{children}<Button type="submit" className="w-full bg-[#B56C78]">儲存</Button></form></DialogContent></Dialog> }
function ConfirmDialog({ request, onClose }: any) { return <Dialog open={Boolean(request)} onOpenChange={next => !next && onClose()}><DialogContent className="rounded-3xl"><DialogHeader><DialogTitle>{request?.title}</DialogTitle><DialogDescription>{request?.text}</DialogDescription></DialogHeader><div className="mt-4 flex justify-end gap-2"><Button type="button" variant="outline" onClick={onClose}>取消</Button><Button type="button" variant="destructive" onClick={() => { request?.run(); onClose(); }}>確認</Button></div></DialogContent></Dialog> }
